// Messages the agent could not answer from the help documents (escalated, reason not_in_docs).
// The agent already made that call in Workflow B. Here they are only collected, so AI can name their topics.
const data = $('Read Messages').first().json || {};
const msgs = Array.isArray(data.messages) ? data.messages : [];

const questions = msgs
  .filter(m => m.escalation_reason === 'not_in_docs')
  .map(m => {
    const raw = String(m.message || '');
    const s = raw.match(/^Subject: ([^\n]*)\n+([\s\S]*)$/);
    const text = s ? (s[1].trim() + ': ' + s[2].trim()) : raw.trim();
    return { id: Number(m.id), text: text.replace(/\s+/g, ' ').slice(0, 400) };
  });

return [{ json: { count: questions.length, questions, questions_json: JSON.stringify(questions) } }];

// The owner's daily report. Code does all the counting.
// AI only named the topics of questions the help documents could not answer ("AI: Label Topics").
const LA = 'America/Los_Angeles';
const TICKETS_URL = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_TICKETS_TABLE_ID';
const TOPIC_NAMES = {
  shipping_delay: 'Shipping delay', missing_package: 'Missing package',
  damaged_or_wrong_item: 'Damaged or wrong item', skin_reaction: 'Skin reaction',
  product_not_suitable: 'Product not suitable', billing_or_subscription: 'Billing or subscription',
  duties_or_fees: 'Duties or fees', service: 'Service', other: 'Other',
};

const ran = name => { try { return $(name).isExecuted; } catch (e) { return false; } };
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : (many || one + 's'));
const now = $now.setZone(LA);

const data = $('Read Messages').first().json || {};
const msgs = Array.isArray(data.messages) ? data.messages : [];
const count = f => msgs.filter(f).length;
const sections = [];

sections.push(':bar_chart: *Saltgrove support · ' + now.toFormat('ccc, LLL d') + '*  (last 24 hours, to ' + now.toFormat('h:mm a') + ' PT)');

// 1. First line: is anyone still waiting for a person? (open tickets in Airtable)
const ticketItems = ran('Read Open Tickets') ? $('Read Open Tickets').all().map(i => i.json || {}) : [];
const ticketsFailed = !ran('Read Open Tickets') || ticketItems.some(t => t.error);
const tickets = ticketItems
  .filter(t => typeof t.id === 'string' && t.id.startsWith('rec'))
  .map(t => { const f = t.fields || t; return { num: f.Ticket, urgent: f.Urgency === 'urgent', created: f.Created || t.createdTime || null }; });

if (ticketsFailed) {
  sections.push(':warning: *Could not read the tickets from Airtable today.* Check them in Airtable.');
} else if (!tickets.length) {
  sections.push(':white_check_mark: *No tickets are waiting for a person.*');
} else {
  const urgent = tickets.filter(t => t.urgent).length;
  const oldest = tickets.filter(t => t.created).sort((a, b) => String(a.created).localeCompare(String(b.created)))[0];
  let line = ':hourglass_flowing_sand: *' + plural(tickets.length, 'ticket') + (tickets.length === 1 ? ' is' : ' are') + ' waiting for a person.*';
  if (urgent) line += ' ' + urgent + ' urgent.';
  if (oldest) {
    const hours = Math.max(0, Math.floor((Date.now() - new Date(oldest.created).getTime()) / 3600000));
    line += ' Oldest: ticket #' + oldest.num + ', open for ' + (hours < 24 ? plural(hours, 'hour') : plural(Math.floor(hours / 24), 'day')) + '.';
  }
  sections.push(line);
}

// 2. Messages in the last 24 hours, by what happened to them.
if (!msgs.length) {
  sections.push('*Messages:* none in the last 24 hours.');
} else {
  const chat = count(m => m.channel === 'chat');
  const lines = ['*Messages:* ' + msgs.length + ' (' + chat + ' chat, ' + (msgs.length - chat) + ' email)'];
  lines.push('• Answered by the bot: ' + count(m => m.route === 'answered'));
  lines.push('• Passed to the team: ' + count(m => m.route === 'escalated'));
  const extra = [];
  const spam = count(m => m.route === 'spam');
  const human = count(m => m.route === 'human');
  if (spam) extra.push('Spam: ' + spam);
  if (human) extra.push('In threads a person is handling: ' + human);
  if (extra.length) lines.push('• ' + extra.join(' · '));
  sections.push(lines.join('\n'));
}

// 3. Top complaint topics (set by triage), counted by code per conversation,
//    so a customer who writes three times about one broken jar counts once.
const byTopic = {};
msgs.filter(m => m.route !== 'spam' && m.complaint_topic && m.complaint_topic !== 'none')
  .forEach(m => { (byTopic[m.complaint_topic] = byTopic[m.complaint_topic] || new Set()).add(m.session_id || ('msg:' + m.id)); });
const top = Object.entries(byTopic).map(([t, set]) => [t, set.size])
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 3);
sections.push(top.length
  ? '*Top complaints:*\n' + top.map(([t, n], i) => (i + 1) + '. ' + (TOPIC_NAMES[t] || t) + ': ' + plural(n, 'customer')).join('\n')
  : '*Top complaints:* none.');

// 4. Asked, but not in the help documents. AI named the topics; code groups and counts them.
const questions = (ran('Find Questions') && $('Find Questions').first().json.questions) || [];
let labelsMissing = false;
if (questions.length) {
  const out = ran('AI: Label Topics') ? ($('AI: Label Topics').first().json.output || {}) : {};
  const labels = {};
  (Array.isArray(out.labels) ? out.labels : []).forEach(l => {
    if (l && l.topic) labels[Number(l.id)] = String(l.topic).trim();
  });
  const groups = new Map();
  questions.forEach(qn => {
    let topic = labels[qn.id];
    if (!topic) {
      labelsMissing = true;
      topic = '"' + (qn.text.length > 80 ? qn.text.slice(0, 80) + '…' : qn.text) + '"';
    }
    const key = topic.toLowerCase();
    const g = groups.get(key) || { topic, n: 0 };
    g.n += 1;
    groups.set(key, g);
  });
  const lines = [...groups.values()].sort((a, b) => b.n - a.n)
    .map(g => '• ' + g.topic + (g.n > 1 ? ' (' + g.n + ')' : ''));
  sections.push('*Asked, but not in the help docs* (worth adding):\n' + lines.join('\n'));
}

// 5. Customers the bot could not help.
const problems = [];
const emailErrors = count(m => m.route === 'error' && m.channel === 'email');
const chatErrors = count(m => m.route === 'error' && m.channel === 'chat');
if (emailErrors) problems.push(':warning: ' + plural(emailErrors, 'email') + ' could not be answered by the AI. Check that someone replied.');
if (chatErrors) problems.push(':warning: ' + plural(chatErrors, 'chat message') + ' got "please try again" because the AI failed.');
if (labelsMissing) problems.push('_Some questions are shown as written: the AI could not name their topics._');
if (problems.length) sections.push(problems.join('\n'));

sections.push('<' + TICKETS_URL + '|Open tickets in Airtable>');

return [{ json: { text: sections.join('\n\n'), messages: msgs.length, open_tickets: tickets.length } }];
